/* ===================== PC 布局（宽度≥900px 生效） ===================== */
@media screen and (min-width: 900px) {
  html, body { background: #eef0f2; }
  body { font-size: 14px; }

  /* 内容居中，两侧留白 */
  #app { max-width: 1180px; margin: 0 auto; background: #fff; min-height: 100vh;
         box-shadow: 0 0 40px rgba(0,0,0,.07); }

  /* 底部 tabbar 改为顶部水平导航 */
  .van-tabbar--fixed { top: 0; bottom: auto; left: 50%; transform: translateX(-50%);
                       width: 100%; max-width: 1180px; height: 56px;
                       box-shadow: 0 1px 0 #eceef0; border-top: none; }
  .van-tabbar { display: flex; }
  .van-tabbar-item { flex: 0 0 auto; min-width: 128px; flex-direction: row; gap: 8px;
                     font-size: 14px; }
  .van-tabbar-item__icon { font-size: 20px; margin-bottom: 0 !important; }

  /* 页面顶部留出导航高度 */
  .van-nav-bar--fixed { top: 56px; left: 50%; transform: translateX(-50%);
                        width: 100%; max-width: 1180px; }
  .page, .van-pull-refresh, .home, #app > div { padding-top: 0; }

  /* 顶部搜索条、横幅宽度收敛 */
  .van-search { max-width: 100%; }

  /* 宫格：大屏一行 10 个 */
  .grid-9, .grid9, .van-grid { --n: 10; }

  /* 弹窗/选择器在 PC 上居中且限宽 */
  .van-popup--bottom { left: 50%; transform: translateX(-50%); max-width: 720px;
                       border-radius: 12px 12px 0 0; }
  .van-dialog { max-width: 420px; }

  /* 活动卡片两列排布 */
  .act-list, .list-box { display: grid; grid-template-columns: repeat(2, minmax(0,1fr));
                         gap: 14px; }
  .act-list > *, .list-box > * { margin-bottom: 0 !important; }

  /* 滚动条 */
  ::-webkit-scrollbar { width: 8px; height: 8px; }
  ::-webkit-scrollbar-thumb { background: #d5d8dc; border-radius: 4px; }
  ::-webkit-scrollbar-track { background: #f4f5f6; }
}

/* ===== PC 修正 2：控制大图/横幅高度 + tabbar 置顶 ===== */
@media screen and (min-width: 900px) {
  /* 横幅、轮播限高，避免宽屏被拉得过高 */
  #app img { max-width: 100%; }
  .swipe, .banner, .van-swipe, .van-swipe-item { max-height: 220px !important; }
  .van-swipe-item img, .swipe img, .banner img { max-height: 220px !important;
      width: 100% !important; object-fit: cover; border-radius: 10px; }

  /* tabbar 置顶（覆盖 vant 的 bottom:0） */
  .van-tabbar--fixed {
    top: 0 !important; bottom: auto !important; left: 0 !important; right: 0 !important;
    transform: none !important; max-width: 1180px !important; margin: 0 auto !important;
    height: 54px !important; box-shadow: 0 1px 0 #eceef0 !important;
    border-top: none !important; z-index: 2000 !important;
  }
  .van-tabbar-item { flex-direction: row !important; gap: 8px; font-size: 14px; }
  .van-tabbar-item__icon { font-size: 20px !important; margin-bottom: 0 !important; }

  /* 给内容让出顶部导航高度 */
  .van-nav-bar--fixed { top: 54px !important; }

  /* 卡片两列 */
  .van-cell-group, .list, .act-list { max-width: 100%; }
}
